shell_commands:
cat tsconfig.json && cat .lore/test-commands.yml && ls node_modules/.package-lock.json >/dev/null 2>&1; node -e "
const lock = require('./package-lock.json');
const pkgs = Object.entries(lock.packages).filter(([k]) => k.includes('ajv'));
for (const [k,v] of pkgs) console.log(k, v.version);
"

rm probe.ts tsconfig.probe.json && node -e "
const l = require('./package-lock.json');
console.log('lock typescript:', l.packages['node_modules/typescript']?.version);
console.log('installed:', require('typescript/package.json').version);
console.log('lock ajv:', l.packages['node_modules/ajv']?.version, l.packages['node_modules/ajv']?.resolved);
" && node -e "console.log(require('fs').readFileSync('node_modules/ajv/dist/ajv.js','utf8').split('\n').filter(l=>/export|module/.test(l)).slice(0,5))"

node -e "
const rules = require('@re-cinq/eslint-plugin-re-lint').rules;
for (const n of ['max-boolean-operators','max-member-chain','prefer-early-return','preserve-caught-error']) {
  const r = rules[n];
  const src = (r && (r.create ? r.create.toString() : JSON.stringify(r))) || 'MISSING';
  console.log('===', n, '===');
  console.log(src.slice(0, 700));
}
" 2>&1 | head -60

node -e "
const rules = require('@re-cinq/eslint-plugin-re-lint').default.rules;
for (const n of ['max-boolean-operators','max-member-chain','prefer-early-return']) {
  const src = rules[n].create.toString();
  const m = src.match(/default[A-Za-z]*\s*[:=]\s*[0-9]+|maxLength|threshold|maxOps|=>\s*[0-9]+/g);
  console.log(n, '->', m);
}
"

grep -rn "max-boolean-operators" node_modules/@re-cinq/eslint-plugin-re-lint/dist/*.js | head -3; node -e "
const fs = require('fs');
const files = fs.readdirSync('node_modules/@re-cinq/eslint-plugin-re-lint/dist');
for (const f of files) {
  const s = fs.readFileSync('node_modules/@re-cinq/eslint-plugin-re-lint/dist/' + f, 'utf8');
  const i = s.indexOf('max-boolean-operators');
  if (i >= 0) console.log(f, '->', s.slice(i, i + 400).replace(/\n/g, ' ').slice(0, 380));
}"
